#include "5c51407df3f73b00_owner_events.hpp"
#include <initializer_list>
namespace recovered_owner_events{
U construct(U self,Ports&p){for(U off:{8u,12u,4u,20u,24u,16u,32u,36u,28u,44u,48u,40u})p.write(self+off,0);return self;}
U before(U list,U data,U position,Ports&p){if(!position)return 0;U node=p.allocate(12);if(node){p.write(node+8,0);p.write(node+4,0);p.write(node,0);}p.write(node+4,position);p.write(node,p.read(position));U previous=p.read(position);if(previous)p.write(previous+4,node);p.write(position,node);p.write(node+8,data);if(!p.read(list+4))p.write(list+4,node);if(p.read(list)==position)p.write(list,node);p.write(list+8,p.read(list+8)+1);return node;}
static void put(U list,U index,U value,Ports&p){if(static_cast<std::int32_t>(index)>=static_cast<std::int32_t>(p.read(list+4))){U count=index+1;if(count)p.grow(list,count);else if(p.read(list)){p.release(p.read(list));p.write(list,0);p.write(list+8,0);}p.write(list+4,count);}p.write(p.read(list)+index*4,value);}
void integer(U s,U i,U v,Ports&p){put(s+4,i,v,p);}void object(U s,U i,U v,Ports&p){put(s+40,i,v,p);}
U add_time(U clock,U day,U tick,U deltaDay,U deltaTick,U outDay,U outTick,Ports&p){U bound=p.read(clock+0x3c);if(tick>=bound||deltaTick>=bound)return 0xfffffffe;p.write(outDay,day+deltaDay);p.write(outTick,tick+deltaTick);if(tick+deltaTick>=p.read(clock+0x3c)){p.write(outDay,p.read(outDay)+1);p.write(outTick,p.read(outTick)-p.read(clock+0x3c));}return 0;}
U compare(U clock,U d1,U t1,U d2,U t2,Ports&p){U bound=p.read(clock+0x3c);if(t1>=bound||t2>=bound)return 0xfffffffe;if(d1==d2)return t1>t2?1:t1<t2?0xffffffff:0;return d1>d2?1:0xffffffff;}
U insert(U self,U day,U tick,U source,U target,U kind,U data,U scratch,Ports&p){if(p.debug())p.trace(kind,source,target,data);U entry=p.allocate(24);p.write(entry+8,source);p.write(entry,day);p.write(entry+4,tick);p.write(entry+12,target);p.write(entry+16,kind);p.write(entry+20,data);p.write(scratch,p.read(p.read(self+0x54)));bool done=false;while(p.read(scratch)&&!done){U current=p.list_get(p.read(self+0x54),p.read(scratch));U clock=p.read(p.read(self)+0x10048);if(compare(clock,p.read(current),p.read(current+4),day,tick,p)==1){p.list_before(p.read(self+0x54),entry,p.read(scratch));done=true;}else p.list_next(p.read(self+0x54),scratch);}if(!done)p.list_append(p.read(self+0x54),entry);return 1;}
U enqueue(U self,U delayDay,U delayTick,U source,U target,U kind,U data,U scratch,Ports&p){p.state_query();p.time(p.read(p.read(self)+0x10048),scratch+4,scratch);U clock=p.read(p.read(self)+0x10048);U error=add_time(clock,p.read(scratch+4),p.read(scratch),delayDay,delayTick,scratch+12,scratch+8,p);if(error){p.release(data);return 0;}return insert(self,p.read(scratch+12),p.read(scratch+8),source,target,kind,data,scratch,p);}
}
